// The Algorithms Workspace (#2761 · #2863 per-kit graph) — render smoke test + the select→inspector
// interaction. The LANGUAGE IS A TAB (`technology-tabs-for-components-and-algorithms`); the LEFT PANE is
// that language's folder tree, and the CENTER is its graph. Every impl name appears in BOTH the rail and
// the canvas, so use getAllByText for anything that isn't inspector-unique (impl code, the role chip).
//
// The seed is TypeScript-first (`TECHS` order), so a Rust case has to select the Rust tab. That is the
// point of the change rather than an inconvenience: reaching a Rust impl is now one deliberate act
// instead of scrolling past every other language's folder.
import { describe, it, expect, beforeAll, beforeEach, vi } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import { AlgorithmsWorkspace } from "@/features/algorithms/AlgorithmsWorkspace";
import { useAppStore } from "@/store";

// The page docks the librarian session (#2787), which mounts an xterm terminal — stub xterm (it can't
// initialize in jsdom) + the layout globals useScreenSession needs, so rendering the page doesn't crash.
vi.mock("@xterm/xterm", () => {
  class Terminal {
    cols = 80; rows = 24; options: Record<string, unknown> = {};
    loadAddon = vi.fn(); open = vi.fn(); write = vi.fn();
    onData = vi.fn(() => ({ dispose: vi.fn() })); focus = vi.fn(); dispose = vi.fn();
    attachCustomKeyEventHandler = vi.fn(); getSelection = vi.fn(() => "");
  }
  return { Terminal };
});
vi.mock("@xterm/addon-fit", () => ({ FitAddon: class { fit = vi.fn(); } }));
vi.mock("@xterm/xterm/css/xterm.css", () => ({}));

beforeAll(() => {
  vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => { cb(0); return 0; });
  vi.stubGlobal("cancelAnimationFrame", () => {});
  vi.stubGlobal("ResizeObserver", class { observe() {} unobserve() {} disconnect() {} });
});

// A rail pick now DRILLS to the impl's layer (`the-algorithms-graph-draws-its-ghost-neighbours`), and the drill
// lives in the app store — which outlives a render. Each case starts on the top layer, as a visit does.
beforeEach(() => { useAppStore.setState({ algorithmsDrill: {} }); });

describe("AlgorithmsWorkspace", () => {
  /** Select a language TAB by its label. */
  const openTech = (label: string) => fireEvent.click(screen.getByText(label));
  /** Enter a GROUP card by its label (`the-algorithms-graph-drills-by-crate`) — the page opens on the
   *  crates and folders of a language, not on its ~2,400 implementations, so a test that wants an impl
   *  CARD drills to it exactly as a reader does. The rail still lists every impl at any layer, so only a
   *  test asserting on the canvas needs this. */
  const drill = (label: string) => fireEvent.click(screen.getAllByText(label)[0]);

  // THE GROUP LAYER DRAWS THE LINKS IT COUNTS (`the-algorithms-group-layer-draws-its-links`). The header's
  // "N links" and the canvas read the same `groupLayer.edges`, and the page once handed that list to the
  // layout and the header but not to the canvas — cards, a count, and no lines. Asserted against the page
  // rather than the canvas alone, because the canvas drawing edges it is given proves nothing about whether
  // the page gives them.
  it("draws every link its group layer counts, in both languages", () => {
    const { container } = render(<AlgorithmsWorkspace />);
    for (const tech of ["TypeScript", "Rust"]) {
      openTech(tech);
      const header = screen.getByText(/groups · \d+ links/).textContent ?? "";
      const counted = Number(/· (\d+) links/.exec(header)?.[1]);
      const drawn = container.querySelectorAll("svg g > path[stroke]").length;
      expect(counted, `${tech}: the seed must give the group layer links to draw`).toBeGreaterThan(0);
      expect(drawn, `${tech}: ${header}`).toBe(counted);
    }
    // The active tab lives in the app store, which outlives this render — leave it where the next case
    // expects to start.
    openTech("TypeScript");
  });

  it("offers a tab per language and shows only that language's impls", () => {
    render(<AlgorithmsWorkspace />);
    // Both languages are TABS now — the level that used to be a rail folder head.
    expect(screen.getByText("Rust")).toBeTruthy();
    expect(screen.getByText("TypeScript")).toBeTruthy();
    // TypeScript is the default tab, so a Rust impl is NOT on screen until its tab is chosen. This is
    // the scoping the tabs buy: the rail carries one language rather than all of them at once.
    expect(screen.queryByText("merge_sort")).toBeNull();
    openTech("Rust");
    expect(screen.getAllByText("merge_sort").length).toBeGreaterThan(0);
    // The on-graph legend (not the inspector) keys the edge types present in the active kit — `composes`
    // is live (every seeded kit has one).
    expect(screen.getByText("Relationships")).toBeTruthy();
    expect(screen.getByText("composes")).toBeTruthy();
  });

  it("selecting an impl shows its code + role in the inspector", () => {
    render(<AlgorithmsWorkspace />);
    openTech("Rust");
    fireEvent.click(screen.getAllByText("merge_sort")[0]);
    expect(screen.getByText((c) => c.includes("merge(&left, &right)"))).toBeTruthy();
    expect(screen.getByText("algorithm")).toBeTruthy(); // the role chip
  });

  it("an algorithm impl lists the impls it builds on (#2863)", () => {
    render(<AlgorithmsWorkspace />);
    openTech("Rust");
    fireEvent.click(screen.getAllByText("merge_sort")[0]);
    expect(screen.getByText("Builds on")).toBeTruthy();
    expect(screen.getAllByText("merge.rs").length).toBeGreaterThan(1); // rail + canvas + builds-on row
  });

  it("a primitive node is visually marked + shows as a descriptor with its std ref (#2899/#2972/#2980)", () => {
    const { container } = render(<AlgorithmsWorkspace />);
    // Open the Rust TAB first (TypeScript is default-active), then drill to where the primitives live —
    // the language built-ins are their own group — and select the primitive's rail row.
    openTech("Rust");
    drill("built-ins");
    fireEvent.click(screen.getAllByText("Iterator")[0]);
    // The primitive node carries the distinct `algo-prim` marker (violet dashed descriptor chip, #2980).
    expect(container.querySelector('[data-impl="rust.iterator"]')?.className).toContain("algo-prim");
    expect(screen.getByText("primitive")).toBeTruthy();
    // A primitive is DESCRIBED by the language built-in it names, not re-coded (#2972) — shown on the
    // node meta AND the inspector, so the ref appears more than once.
    expect(screen.getAllByText((c) => c.includes("std::iter::Iterator")).length).toBeGreaterThan(0);
  });

  // ── GHOSTS + NAVIGATION (`the-algorithms-graph-draws-its-ghost-neighbours`) ───────────────────────────────
  // componentScan (feature:designs) composes componentRuntimeProbe (folder:shared/lib/preview) — a real
  // cross-group edge in the packaged seed. The stub for it used to say "shared/lib/preview · 1 edge".
  const drillOf = () => useAppStore.getState().algorithmsDrill["typescript"] ?? [];
  const impl = (c: HTMLElement, id: string) => c.querySelector(`[data-impl="${id}"]`) as HTMLElement | null;
  /** Pick an implementation in the RAIL, the way a reader does: its folders start collapsed, so search first. */
  const railPick = (name: string) => {
    openTech("TypeScript"); // the tab lives in the store, and an earlier case leaves it on Rust
    fireEvent.change(screen.getByLabelText("Search"), { target: { value: name } });
    // The rail row carries the name AND the record id, so target the row itself rather than a text node.
    const row = [...document.querySelectorAll(".algo-implrow")].find((el) => el.textContent?.includes(name)) as HTMLElement;
    fireEvent.click(row);
  };

  it("drills the GRAPH to an implementation chosen in the rail, and selects it", () => {
    const { container } = render(<AlgorithmsWorkspace />);
    expect(impl(container, "component-scan.ts")).toBeNull(); // the top layer draws groups
    railPick("componentScan");
    expect(drillOf()).toEqual(["feature:designs"]);
    const card = impl(container, "component-scan.ts")!;
    expect(card).toBeTruthy();
    expect(card.hasAttribute("data-ghost")).toBe(false);
    expect(card.className).toContain(" on");
  });

  it("draws the implementation an edge reaches in another group as a GHOST, and goes there on click", () => {
    const { container } = render(<AlgorithmsWorkspace />);
    railPick("componentScan");
    const ghost = impl(container, "component-runtime-probe.ts")!;
    expect(ghost?.hasAttribute("data-ghost")).toBe(true);
    fireEvent.click(ghost);
    expect(drillOf()).toEqual(["folder:shared/lib/preview"]);
    expect(impl(container, "component-runtime-probe.ts")!.hasAttribute("data-ghost")).toBe(false);
    // …and the composer it came from is the ghost now, so the walk goes both ways.
    expect(impl(container, "component-scan.ts")?.hasAttribute("data-ghost")).toBe(true);
  });
});

